import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        int m = scanner.nextInt();

        if (n >= 4 && m >= 4) {
            System.out.println(n * m - (n * m) % 2);
        } else {
            int min = Math.min(n, m);
            int max = Math.max(n, m);
            if (min == 1) {
                int maxVal = max;
                int modVal = maxVal % 6;
                int base = (maxVal / 6) * 6;
                if (modVal == 5) {
                    System.out.println(base + 4);
                } else if (modVal == 4) {
                    System.out.println(base + 2);
                } else {
                    System.out.println(base);
                }
            } else if (min == 2 && max == 7) {
                System.out.println(12);
            } else if ((min == 2 && max >= 4) || (min == 3 && max >= 4)) {
                System.out.println(n * m - (n * m) % 2);
            } else {
                int[][] d = {
                    {0, 0, 0, 2, 4},
                    {0, 0, 4, 8, 10},
                    {0, 0, 8, 12, 14},
                    {0, 0, 0, 16, 20},
                    {0, 0, 0, 0, 24}
                };
                System.out.println(d[min - 1][max - 1]);
            }
        }
        scanner.close();
    }
}
